    w=m_famsign(X); s=sh(X); return w+a*s/np.abs(s).max()*0  # placeholder
def m_mv(X,lam):
    C=np.cov(X.T); d=np.diag(np.diag(C)); C=(1-lam)*C+lam*d
    w=np.linalg.solve(C,X.mean(0)); return w
def m_mvfam(X,lam):
    # mv on family-level demeaned? use shrinkage toward diag
    return m_mv(X,lam)
methods={'sign':m_sign,'sh':m_sh,'famsign':m_famsign,
 'mv0.5':lambda X:m_mv(X,0.5),'mv0.9':lambda X:m_mv(X,0.9),'mv0.99':lambda X:m_mv(X,0.99),'mv0.1':lambda X:m_mv(X,0.1)}
