        tr=np.concatenate([folds[j] for j in range(K) if j!=i]); w=f(R[tr]); oos.append(sh(R[folds[i]]@w))
    # forward-only
    fw=[sh(R[folds[i]]@f(R[np.concatenate(folds[:i])])) for i in range(1,K)]
    print(k,np.round(oos,2),round(np.mean(oos),2),'fwd',np.round(fw,2),round(np.mean(fw),2))
for f in sorted(set(fam)):
    x=R[:,fam==f].mean(1); print(f,[round(sh(x[fo]),2) for fo in folds])
