import numpy as np, json
R=np.load('R.npy')
sh=lambda x: x.mean(0)/x.std(0)*np.sqrt(252)
T=len(R); K=10; folds=[np.arange(i*T//K,(i+1)*T//K) for i in range(K)]
def mv(X,lam,hl=None):
    if hl: wt=0.5**(np.arange(len(X))[::-1]/hl); wt/=wt.sum()
    else: wt=np.ones(len(X))/len(X)
    mu=wt@X; Xc=X-mu; C=(Xc*wt[:,None]).T@Xc; C=(1-lam)*C+lam*np.diag(np.diag(C))
    return np.linalg.solve(C,mu)
for lam in [0.2,0.35,0.5,0.7]:
  for hl in [None,252*10,252*5]:
    fw=[sh(R[folds[i]]@mv(R[np.concatenate(folds[:i])],lam,hl)) for i in range(3,K)]
    print(lam,hl,np.round(fw,2),round(np.mean(fw),2))
